export function shippingCost(order) {
  if (!order) return 0;                            // guard clauses first
  if (order.lines.length === 0) return 0;

  const weightKg = order.lines.reduce((kg, line) => kg + line.weightKg, 0);
  return weightKg * RATE_PER_KG;                   // body stays at one level
}
